def choice(exercise_id: str, context: str, question: str, options: list[tuple[str, int, str, str]]) -> dict[str, Any]:
    return {
        "id": exercise_id, "type": "выбор", "context": context, "question": question,
        "options": [{"id": chr(97 + index), "text": text, "quality": quality, "feedback": feedback, "explanation": explanation}
                    for index, (text, quality, feedback, explanation) in enumerate(options)],
    }


